def pre(a, b):
    # Validate input constraints from the problem specification
    if len(a) > 4 or len(b) > 4:
        return False

    # Check all elements are in range [-9, 9]
    for x in a:
        if x < -9 or x > 9:
            return False
    for x in b:
        if x < -9 or x > 9:
            return False

    # Check non-decreasing order
    for i in range(len(a) - 1):
        if a[i] > a[i + 1]:
            return False
    for i in range(len(b) - 1):
        if b[i] > b[i + 1]:
            return False

    return True

def post(a, b, result):
    # The result must equal the sorted merge of a and b:
    # - it contains all elements from both lists (with repetitions)
    # - it is sorted in non-decreasing order
    return result == sorted(a + b)
